import {CONFIG as C} from './config.js';
import {GROUPS} from './foods.js';
import {clamp} from './model.js';
import {wheelGeometry} from './geometry.js';
const hash=n=>{n=(n^61)^(n>>>16);n=Math.imul(n,9);n=n^(n>>>4);n=Math.imul(n,0x27d4eb2d);n=n^(n>>>15);return (n>>>0)/4294967296;};
export class Renderer{
 constructor(canvas,assets){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.assets=assets;this.particles=[];this.spin=0;this.pose=0;this.road=this.makeRoad();this.trees=[0,1,2].map(i=>this.makeTree(i));}
 resize(){const bounds=this.canvas.getBoundingClientRect?.();const width=Math.max(C.width,Math.round((bounds?.width||C.width)*(globalThis.devicePixelRatio||1)));if(this.canvas.width!==width){this.canvas.width=width;this.canvas.height=Math.round(width*C.height/C.width);}}
 rect(x,y,w,h,color){this.ctx.fillStyle=color;this.ctx.fillRect(Math.round(x/2)*2,Math.round(y/2)*2,Math.round(w/2)*2,Math.round(h/2)*2);}
 poly(points,color,stroke,width=2){const c=this.ctx;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(Math.round(x/2)*2,Math.round(y/2)*2):c.moveTo(Math.round(x/2)*2,Math.round(y/2)*2));c.closePath();if(color){c.fillStyle=color;c.fill();}if(stroke){c.lineWidth=width;c.strokeStyle=stroke;c.stroke();}}
 line(points,color,width=2){const c=this.ctx;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(Math.round(x/2)*2,Math.round(y/2)*2):c.moveTo(Math.round(x/2)*2,Math.round(y/2)*2));c.strokeStyle=color;c.lineWidth=width;c.lineJoin='miter';c.stroke();}
 circle(x,y,r,color,stroke,width=2){this.poly(Array.from({length:40},(_,i)=>[x+Math.cos(i*Math.PI/20)*r,y+Math.sin(i*Math.PI/20)*r]),color,stroke,width);}
 icon(id,x,y,size){const img=this.assets.icons[id];if(img){const old=this.ctx.imageSmoothingEnabled;this.ctx.imageSmoothingEnabled=true;this.ctx.drawImage(img,Math.round(x/2)*2,Math.round(y/2)*2,size,size);this.ctx.imageSmoothingEnabled=old;}}
 makeRoad(){const cv=document.createElement('canvas');cv.width=256;cv.height=128;const c=cv.getContext('2d');c.fillStyle='#969394';c.fillRect(0,0,256,128);for(let i=0;i<1000;i++){c.fillStyle=i%3?'#8d8c8f':'#a29e9c';c.fillRect(Math.floor(hash(i)*256),Math.floor(hash(i+2398)*128),1+Math.floor(hash(i+256)*4),1);}return cv;}
 makeTree(type){const cv=document.createElement('canvas');cv.width=68;cv.height=79;const c=cv.getContext('2d');c.fillStyle='#5c6548';c.fillRect(30,37,9,40);c.fillStyle='#b09564';c.fillRect(33,49,3,22);const colors=[['#315949','#4c7948','#6e9b4d','#95b44e'],['#234f47','#3c744b','#64924c','#8bb247'],['#36624a','#568849','#85a64d','#b0bb56']][type];for(let i=0;i<65;i++){const x=Math.floor(8+hash(i+type*37)*49),y=Math.floor(5+hash(i+129+type*11)*45),r=4+Math.floor(hash(i+300)*10);c.fillStyle=colors[i%4];c.fillRect(x-r/2,y,r,r);c.fillRect(x-r/2-2,y+2,r+4,r-4);}return cv;}
 background(distance){const c=this.ctx;this.rect(0,0,1280,250,'#85c9e4');this.rect(0,0,1280,112,'#76bfe0');
  const cloudShift=(distance*C.scenery.cloud)%440;for(let x=-440;x<1500;x+=440){this.rect(x-cloudShift+40,137,146,10,'#b2dce9');this.rect(x-cloudShift+58,124,88,14,'#b2dce9');this.rect(x-cloudShift+71,118,30,8,'#c3e5ee');}
  const mountainShift=(distance*C.scenery.mountain)%520;for(let x=-520;x<1560;x+=520){this.poly([[x-mountainShift,248],[x+150-mountainShift,136],[x+210-mountainShift,169],[x+280-mountainShift,207],[x+370-mountainShift,151],[x+520-mountainShift,248]],'#91ab87');this.poly([[x+30-mountainShift,248],[x+150-mountainShift,146],[x+145-mountainShift,186],[x+193-mountainShift,186],[x+230-mountainShift,248]],'#a7b58a');}
  const shift=(distance*C.scenery.tree)%136;for(let x=-136;x<1416;x+=136)c.drawImage(this.trees[Math.floor((x+136)/136)%3],x-shift,150,136,158);
  this.rect(0,245,1280,30,'#567b48');for(let i=0;i<160;i++){let x=(i*38-distance*C.scenery.rail)%1340;if(x<0)x+=1340;this.rect(x,248+hash(i)*20,6,4,i%7===0?'#f7d884':'#8cb652');}
  // Festival rail, bunting and individual cheering spectators.
  const railShift=(distance*C.scenery.rail)%160;
  for(let x=-160;x<1440;x+=160){const xx=x-railShift;this.rect(xx,287,80,23,'#d76764');this.rect(xx+80,287,80,23,'#f3e8d3');this.rect(xx,283,160,6,'#7b8b80');this.rect(xx+8,288,5,25,'#657872');this.rect(xx+83,290,63,3,'#d3d1ba');this.person(xx+25,280,Math.floor((x+160)/160));}
  this.line([[0,280],[1280,280]],'#334d46',4);
  const flags=(distance*C.scenery.rail)%380;for(let x=-380;x<1660;x+=380){this.rect(x-flags+10,213,4,69,'#715743');this.line([[x-flags+10,225],[x-flags+210,240],[x-flags+390,222]],'#826e4a',2);for(let n=0;n<8;n++){const fx=x-flags+28+n*44;this.poly([[fx,228+n%3*4],[fx+22,230+n%3*4],[fx+12,250+n%3*4]],['#eb655f','#f7ce64','#f7f0d7'][n%3]);}}
  this.rect(0,310,1280,366,'#969394');const pat=c.createPattern(this.road,'repeat');c.save();c.translate(-Math.round(distance*C.scenery.road)%512,310);c.fillStyle=pat;c.fillRect(-512,0,2304,366);c.restore();
  this.rect(0,316,1280,4,'#c9c4b7');this.rect(0,673,1280,4,'#e6e3d0');const laneShift=(distance*C.scenery.road)%100;for(let x=-100;x<1400;x+=100)this.rect(x-laneShift,496,45,5,'#e2e0d4');
  this.rect(0,678,1280,42,'#669947');for(let i=0;i<180;i++){let x=(i*19-distance*C.scenery.foreground)%1360;if(x<0)x+=1360;this.rect(x,680+hash(i+1500)*35,4,8,['#89b74d','#b0c666','#416c43'][i%3]);if(i%7===0){this.rect(x,685+hash(i)*12,8,4,'#fff6d7');this.rect(x+2,683+hash(i)*12,4,8,'#fff6d7');this.rect(x+3,686+hash(i)*12,2,2,'#eec754');}}
  const fence=(distance*C.scenery.foreground)%160;for(let x=-160;x<1440;x+=160){this.rect(x-fence,708,160,7,'#705137');this.rect(x-fence+5,696,12,30,'#825e3d');this.rect(x-fence+7,696,3,30,'#ba8955');}
 }
 person(x,y,i){this.rect(x-10,y-26,19,23,'#263344');this.rect(x-8,y-21,15,15,'#eeb991');this.rect(x-10,y-26,19,8,'#283431');this.rect(x-5,y-15,2,3,'#263344');this.rect(x+3,y-15,2,3,'#263344');this.rect(x-7,y-5,15,11,['#e98291','#8ab5ce','#e9c363'][i%3]);this.rect(x+11,y-18,5,9,'#eeb991');this.rect(x+13,y-24,5,8,'#eeb991');this.rect(x-12,y-3,6,6,'#eeb991');}
 rearWheel(g,x,y,geometry){const c=this.ctx,m=g.m;const {r,map,offsets,radius,outline}=geometry;const ang=this.spin;
  c.save();c.translate(Math.round(x/2)*2,Math.round(y/2)*2);c.rotate(ang);
  this.poly(outline,'#172536','#416285',C.bike.rear.outlineWidth);
  for(let j=0;j<6;j++){const pts=[[0,0]];for(let n=0;n<=18;n++){const a=offsets[j]+(offsets[j+1]-offsets[j])*n/18;pts.push([Math.cos(a)*radius(a),Math.sin(a)*radius(a)]);}this.poly(pts,j===3&&m.K?'#ee7667':GROUPS[map[j]].color);const a=(offsets[j]+offsets[j+1])/2;const rr=r*.62;this.icon(GROUPS[map[j]].icon,Math.cos(a)*rr-16,Math.sin(a)*rr-16,32);}
  this.circle(0,0,7,'#6d8998','#172536',3);c.restore();
 }
 frontWheel(g,x,y){const c=this.ctx;const squash=1-g.m.H*.1;c.save();c.translate(x,y);c.scale(1,squash);this.circle(0,0,45,'#8bddf5','#1b2c41',7);this.circle(0,0,39,'#76c0e5','#3876a6',2);c.save();this.poly(Array.from({length:40},(_,i)=>[Math.cos(i*Math.PI/20)*37,Math.sin(i*Math.PI/20)*37]));c.clip();const waterline=34-g.water/100*66;this.rect(-40,waterline,80,80,'#339bd6');this.rect(-40,waterline,80,3,'#d3f7ff');for(let n=0;n<8;n++){const a=this.spin+n*Math.PI/4;this.line([[0,0],[Math.cos(a)*37,Math.sin(a)*37]],'#b6eaf044',2);}c.restore();this.icon('water',-15,-20,30);if(g.water<25&&Math.floor(g.time*2)%2===0)this.rect(-6,-6,12,14,'#f9ddd0');c.restore();}
 bike(g,dt,offset=0){const c=this.ctx;this.spin+=g.speed*dt*C.scenery.road/72;this.pose+=(Number(g.fast)-this.pose)*Math.min(1,dt/C.poseTransition*3);const geometry=wheelGeometry(g.m,this.spin);const wobble=Math.sin(this.spin*3)*g.m.I*5;const x=C.bike.x+offset,y=g.y+wobble,ground=g.y+C.bike.groundDY,rearY=g.y+geometry.rearY,frontY=g.y+geometry.frontY;this.poly(Array.from({length:32},(_,i)=>[x-14+Math.cos(i*Math.PI/16)*120,ground+4+Math.sin(i*Math.PI/16)*9]),'#353a3844');for(const dx of [-72,74])this.poly(Array.from({length:24},(_,i)=>[x+dx+Math.cos(i*Math.PI/12)*27,ground+Math.sin(i*Math.PI/12)*5]),'#263b4d55');this.poly(Array.from({length:32},(_,i)=>[x+74+Math.cos(i*Math.PI/16)*38,ground+Math.sin(i*Math.PI/16)*17]),null,'#d4f9dc99',2);this.rearWheel(g,x-72,rearY,geometry);this.frontWheel(g,x+74,frontY);
  const frame=[[x-72,rearY],[x-25,y-18],[x+8,y+17],[x-72,rearY],[x+25,y-16],[x+8,y+17],[x+60,y-24],[x+74,frontY]];
  this.line(frame,'#17283b',9);this.line(frame,'#3c82ae',4);this.line([[x-25,y-18],[x-33,y-39]],'#20354b',7);this.line([[x-50,y-40],[x-23,y-40]],'#202b34',8);this.line([[x+60,y-24],[x+56,y-47],[x+40,y-50],[x+34,y-39]],'#14263b',8);this.line([[x+55,y-45],[x+42,y-46]],'#77b5cf',3);
  this.circle(x+8,y+17,12,'#334e64','#182a3d',3);const phase=Math.floor((this.spin*.45/(Math.PI*2)%1+1)%1*4);const a=phase*Math.PI/2;const crank=[x+8,y+17];for(let j=0;j<2;j++){const p=[crank[0]+Math.cos(a+j*Math.PI)*14,crank[1]+Math.sin(a+j*Math.PI)*14];this.line([crank,p],'#c3d4d7',3);this.rect(p[0]-8,p[1],16,4,'#192330');}
  const s=C.bike.sprite;c.save();const drawPose=(row,alpha)=>{if(alpha<.01)return;c.globalAlpha=alpha;c.drawImage(this.assets.rider,phase*160,row*160,160,160,x+s.x,y+s.y,s.w,s.h);};drawPose(0,1-this.pose);drawPose(1,this.pose);c.restore();
  for(let n=0;n<(g.fast?7:4);n++)this.rect(x-132-((g.distance*30+n*37)%140),y-15+n*23,24+g.displayedSpeedKmh*.25+n*3,2,'#edf8ed99');
  for(let n=0;n<6;n++){const p=(g.distance*.9+n*1.3)%5;this.rect(x-135-p*17,ground-4-p*3,12-p,6-p/2,'#eae4d6bb');}
 }
 speedometer(kmh){const c=this.ctx,{x,y,r}=C.speedometer;this.circle(x,y,r+4,'#392b26','#221b24',5);this.circle(x,y,r,'#6d4a33','#bf8f58',3);this.circle(x,y,r-9,'#f7edd1','#201f29',4);this.circle(x,y,r-16,'#eaddba');for(let n=0;n<=20;n++){const a=(140+n/20*260)*Math.PI/180;const major=n%4===0;this.line([[x+Math.cos(a)*(r-21),y+Math.sin(a)*(r-21)],[x+Math.cos(a)*(r-(major?32:27)),y+Math.sin(a)*(r-(major?32:27))]],n>=18?'#bf5b51':'#5a4a3b',major?3:2);if(major){c.fillStyle='#574b3b';c.font='bold 12px sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(String(n*5),x+Math.cos(a)*(r-42),y+Math.sin(a)*(r-42));}}
  const a=(140+clamp(kmh,0,100)/100*260)*Math.PI/180;this.line([[x,y],[x+Math.cos(a)*(r-31),y+Math.sin(a)*(r-31)]],'#c8544c',5);this.circle(x,y,7,'#5b4538');this.rect(x-37,y+30,74,28,'#43352f');c.fillStyle=kmh>=90?'#c8ed83':'#fff1c9';c.font='bold 28px monospace';c.textAlign='center';c.fillText(String(kmh).padStart(2,'0'),x,y+46);c.font='bold 11px sans-serif';c.fillStyle='#746146';c.fillText('km/h',x,y+69);
 }
 addEffect(food,y){for(let i=0;i<10;i++)this.particles.push({x:C.bike.pickup.x,y:y-34,age:0,dx:(hash(i+food.group*17)-.5)*145,dy:-40-hash(i+2)*85,color:food.kind==='spoiled'?'#eb6d57':food.kind==='water'?'#a0e5fa':'#fff5a6'});}
 draw(g,dt,stage,stageTime=0){this.resize();const c=this.ctx;c.save();c.scale(this.canvas.width/C.width,this.canvas.height/C.height);c.imageSmoothingEnabled=false;this.background(g.distance);if(C.finishDistance-g.distance<80){const flagX=C.bike.pickup.x+(C.finishDistance-g.distance)*C.scenery.road;this.rect(flagX-6,300,12,373,'#f1e9d8');for(let yy=318;yy<670;yy+=20)for(let xx=0;xx<2;xx++)this.rect(flagX-15+xx*20,yy,20,20,(Math.floor(yy/20)+xx)%2?'#28303b':'#f2e9d6');this.rect(flagX-60,278,120,24,'#43322b');c.fillStyle='#f6e9cb';c.font='bold 16px sans-serif';c.textAlign='center';c.fillText('FINISH',flagX,296);}
  for(const item of [...g.items].sort((a,b)=>a.y-b.y)){const food=item.food,needed=food.kind==='food'&&food.group===g.m.counts.map((v,i)=>v/C.targets[i]).indexOf(Math.min(...g.m.counts.map((v,i)=>v/C.targets[i])));this.poly(Array.from({length:24},(_,i)=>[item.x+Math.cos(i*Math.PI/12)*25,item.y+Math.sin(i*Math.PI/12)*7]),'#37403855');if(needed)this.poly(Array.from({length:24},(_,i)=>[item.x+Math.cos(i*Math.PI/12)*30,item.y+Math.sin(i*Math.PI/12)*10]),null,'#e5f6bbaa',2);this.icon(food.id,item.x-C.itemSize/2,item.y-C.itemSize-6,C.itemSize);c.font=`bold ${C.itemLabelSize}px "Malgun Gothic",sans-serif`;c.textAlign='center';c.textBaseline='middle';const label=food.label||food.name,w=c.measureText(label).width+18;this.rect(item.x-w/2,item.y+10,w,24,food.kind==='spoiled'?'#653f39e8':'#fff4dae8');c.fillStyle=food.kind==='spoiled'?'#ffddd2':'#43372b';c.fillText(label,item.x,item.y+22);}
  const running=stage==='running'||stage==='finish';this.bike(g,running?dt:0,stage==='finish'?stageTime*210:0);for(const p of this.particles){if(running){p.age+=dt;p.x+=p.dx*dt;p.y+=p.dy*dt;}const s=5*(1-p.age/.7);if(s>0)this.rect(p.x,p.y,s,s,p.color);}this.particles=this.particles.filter(p=>p.age<.7);
  this.speedometer(['start','countdown'].includes(stage)?0:g.displayedSpeedKmh);c.restore();
 }
}
